fn largest_divisor(n: i8) -> i8 {
    assert!(n > 1);

    // The largest proper divisor of n is n / p where p is the smallest prime factor of n.
    // We can find the smallest divisor d >= 2; then answer is n / d.
    let n_i32 = n as i32;

    let mut d: i32 = 2;
    while d * d <= n_i32 {
        if n_i32 % d == 0 {
            return (n_i32 / d) as i8;
        }
        d += 1;
    }

    // If no divisor found up to sqrt(n), n is prime, so largest proper divisor is 1.
    1
}